import Vue from 'vue';
import VueApollo from 'vue-apollo';
import { parseBoolean } from '@gitlab/frontend-utils';
import { initVueApp } from '~/lib/utils/vue3compat/init_vue_app';
import createDefaultClient from '~/lib/graphql';
import { showAlertFromLocalStorage } from '~/lib/utils/local_storage_alert';
import ProjectRunnersSettingsApp from './project_runners_settings_app.vue';

Vue.use(VueApollo);

export const initProjectRunnersSettings = (selector = '#js-project-runners-settings') => {
  showAlertFromLocalStorage();

  const el = document.querySelector(selector);

  if (!el) {
    return null;
  }

  const apolloProvider = new VueApollo({
    defaultClient: createDefaultClient(),
  });

  const {
    projectId,
    canCreateRunner,
    canAssignRunners,
    canUnassignRunners,
    canCreateRunnerForGroup,
    canToggleGroupRunners,
    groupRunnersEnabled,
    groupRunnersPath,
    allowRegistrationToken,
    registrationToken,
    newProjectRunnerPath,
    projectFullPath,

    canToggleInstanceRunners,
    instanceRunnersEnabled,
    instanceRunnersDisabledAndUnoverridable,
    instanceRunnersUpdatePath,
    instanceRunnersGroupSettingsPath,
    groupName,
  } = el.dataset;

  return initVueApp({
    el,
    name: 'ProjectRunnersSettingsAppRoot',
    apolloProvider,
    provide: {
      projectId,
      canCreateRunnerForGroup: parseBoolean(canCreateRunnerForGroup),
      canToggleGroupRunners: parseBoolean(canToggleGroupRunners),
      isGroupRunnersEnabled: parseBoolean(groupRunnersEnabled),
      canToggleInstanceRunners: parseBoolean(canToggleInstanceRunners),
      canAssignRunners: parseBoolean(canAssignRunners),
      canUnassignRunners: parseBoolean(canUnassignRunners),
      groupRunnersPath,
    },
    component: ProjectRunnersSettingsApp,
    props: {
      canCreateRunner: parseBoolean(canCreateRunner),
      allowRegistrationToken: parseBoolean(allowRegistrationToken),
      registrationToken,
      newProjectRunnerPath,
      projectFullPath,

      instanceRunnersEnabled: parseBoolean(instanceRunnersEnabled),
      instanceRunnersDisabledAndUnoverridable: parseBoolean(
        instanceRunnersDisabledAndUnoverridable,
      ),
      instanceRunnersUpdatePath,
      instanceRunnersGroupSettingsPath,
      groupName,
    },
  });
};
